mapper.sql:
where user_id = #{userId} and notification_id <= #{snapshotMaxId}

    and (title like #{query.keywordPattern} escape '!' or body like #{query.keywordPattern} escape '!')

and route_type = #{query.routeType}
and read_status = #{query.readStatus}
and create_time >= #{query.startTime}
and create_time < #{query.endTimeExclusive}

mapper.update:
update sys_user_notification
set read_status = '1',
    read_time = sysdate()
where notification_id = #{notificationId}
  and user_id = #{userId}
  and read_status = '0'
